			filteredRows.push(row);
			newFilteredFlatRows.push(row);
			newFilteredRowsById[row.id] = row;
			if (row.subRows.length && depth >= maxDepth) addSubRowsToFlatArrays(row.subRows, newFilteredFlatRows, newFilteredRowsById);
